    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        String marketId = this.safeString(ticker, "symbol");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, (String) null, (String) null);
        Long timestamp = null;
        String bid = null;
        String ask = null;
        String bidVolume = null;
        String askVolume = null;
        String baseVolume = null;
        String quoteVolume = null;
        String open = null;
        String high = null;
        String low = null;
        String changePcnt = null;
        String changeValue = null;
        String prevClose = null;
        Boolean isSwap = (Boolean) this.safeBool(marketResolved, "swap", (Object) null);
        // if swap
        if ((java.util.Objects.equals(isSwap, true)) || (((Map<?, ?>)ticker).containsKey("timestamp")))
        {
            //
            //     {
            //         "symbol": "ETH_USDT",
            //         "lastPrice": 3581.3,
            //         "bid1": 3581.25,
            //         "ask1": 3581.5,
            //         "volume24": 4045530,
            //         "amount24": 141331823.5755,
            //         "holdVol": 5832946,
            //         "lower24Price": 3413.4,
            //         "high24Price": 3588.7,
            //         "riseFallRate": 0.0275,
            //         "riseFallValue": 95.95,
            //         "indexPrice": 3580.7852,
            //         "fairPrice": 3581.08,
            //         "fundingRate": 0.000063,
            //         "maxBidPrice": 3938.85,
            //         "minAskPrice": 3222.7,
            //         "timestamp": 1634162885016
            //     }
            //
            timestamp = this.safeInteger(ticker, "timestamp");
            bid = this.safeString(ticker, "bid1");
            ask = this.safeString(ticker, "ask1");
            baseVolume = this.safeString(ticker, "volume24");
            quoteVolume = this.safeString(ticker, "amount24");
            high = this.safeString(ticker, "high24Price");
            low = this.safeString(ticker, "lower24Price");
            changeValue = this.safeString(ticker, "riseFallValue");
            changePcnt = this.safeString(ticker, "riseFallRate");
            changePcnt = Precise.stringMul(changePcnt, "100");
        } else
        {
            //
            //     {
            //         "symbol": "BTCUSDT",
            //         "priceChange": "184.34",
            //         "priceChangePercent": "0.00400048",
            //         "prevClosePrice": "46079.37",
            //         "lastPrice": "46263.71",
            //         "lastQty": "",
            //         "bidPrice": "46260.38",
            //         "bidQty": "",
            //         "askPrice": "46260.41",
            //         "askQty": "",
            //         "openPrice": "46079.37",
            //         "highPrice": "47550.01",
            //         "lowPrice": "45555.5",
            //         "volume": "1732.461487",
            //         "quoteVolume": null,
            //         "openTime": 1641349500000,
            //         "closeTime": 1641349582808,
            //         "count": null
            //     }
            //
            timestamp = this.safeInteger(ticker, "closeTime");
            bid = this.safeString(ticker, "bidPrice");
            ask = this.safeString(ticker, "askPrice");
            bidVolume = this.safeString(ticker, "bidQty");
            askVolume = this.safeString(ticker, "askQty");
            if (Precise.stringEq(bidVolume, "0"))
            {
                bidVolume = null;
            }
            if (Precise.stringEq(askVolume, "0"))
            {
                askVolume = null;
            }
            baseVolume = this.safeString(ticker, "volume");
            quoteVolume = this.safeString(ticker, "quoteVolume");
            open = this.safeString(ticker, "openPrice");
            high = this.safeString(ticker, "highPrice");
            low = this.safeString(ticker, "lowPrice");
            prevClose = this.safeString(ticker, "prevClosePrice");
            changeValue = this.safeString(ticker, "priceChange");
            changePcnt = this.safeString(ticker, "priceChangePercent");
            changePcnt = Precise.stringMul(changePcnt, "100");
        }
        return this.safeTicker(Helpers.newMap(
            "symbol", ((Map<String, Object>)marketResolved).get("symbol"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "open", open,
            "high", high,
            "low", low,
            "close", this.safeString(ticker, "lastPrice"),
            "bid", bid,
            "bidVolume", bidVolume,
            "ask", ask,
            "askVolume", askVolume,
            "vwap", null,
            "previousClose", prevClose,
            "change", changeValue,
            "percentage", changePcnt,
            "average", null,
            "baseVolume", baseVolume,
            "quoteVolume", quoteVolume,
            "info", ticker
        ), Helpers.toMapArg(marketResolved));
    }

